import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Njia ya Msingi ya Kuchukia Uhalisi kama Msingi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/09-现实为基根本立场.md","filePath":"sw/09-现实为基根本立场.md","lastUpdated":null}'),s={name:"sw/09-现实为基根本立场.md"};function h(t,a,e,o,w,l){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="njia-ya-msingi-ya-kuchukia-uhalisi-kama-msingi" tabindex="-1">Njia ya Msingi ya Kuchukia Uhalisi kama Msingi <a class="header-anchor" href="#njia-ya-msingi-ya-kuchukia-uhalisi-kama-msingi" aria-label="Permalink to &quot;Njia ya Msingi ya Kuchukia Uhalisi kama Msingi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>09</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Kuchukia Uhalisi kama Msingi, Uhalisi wa Pekee, Mipaka ya Ufisadi, Sasisho la Sheria, Uthibitisho wa Mazoezi</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-msingi-wa-kuchukia-uhalisi-kama-msingi" tabindex="-1">1. Ufafanuzi wa Msingi wa Kuchukia Uhalisi kama Msingi <a class="header-anchor" href="#_1-ufafanuzi-wa-msingi-wa-kuchukia-uhalisi-kama-msingi" aria-label="Permalink to &quot;1. Ufafanuzi wa Msingi wa Kuchukia Uhalisi kama Msingi&quot;">​</a></h2><p>Kuchukia uhalisi kama msingi ni msimamo wa msingi wa epistemolojia na kanuni ya mbinu ya Ustaarabu wa Usawa wa Nanga, inayomaanisha kuwa majengo yote ya kibunifu, michoro ya taasisi, mazoezi ya uozi, na ubunifu wa teknolojia wa ustaarabu vinapaswa kuchukia ulimwengu wa kweli kama msingi wa kweli wa pekee na kriteria ya mwisho ya kuthibitisha. &quot;Uhalisi&quot; inarejelea ulimwengu wa vifaa na ulimwengu wa nishati wa uwepo wa kisayansi ambao unaweza kuchunguzwa, kupimwa, na kuthibitishwa, na ni mahali pa kweli pa kuishi na mageuzi ya uhai.</p><p>Msimamo wa kuchukia uhalisi kama msingi una tabaka tatu za maana: kwanza, ulimwengu wa kweli ndio ulimwengu wa kweli wa pekee, na ulimwengu wa ufisadi (ikiwa ni pamoja na riwaya, hadithi za jadi, na ulimwengu wa fantasia) ni bidhaa za majaribio ya akili na hazina uhalisi wa kisayansi; pili, mipangilio ya ulimwengu wa ufisadi inaweza kutumika kama vyanzo vya uhamasisho na zana za majaribio ya akili, lakini haziwezi kutumika moja kwa moja kama msingi wa uhalisi, na lazima zipite katika kuthibitishwa na mabadiliko ya sheria za kweli; tatu, mambo ambayo bado hayapo katika uhalisi yanaweza kutekwa na kuundwa kwa busara kulingana na sheria za kisayansi zilizothibitishwa tayari, lakini uumbaji huu lazima ukubali kuthibitishwa kwa mazoezi.</p><h2 id="_2-kwa-nini-lazima-tudumishi-kuchukia-uhalisi-kama-msingi" tabindex="-1">2. Kwa nini lazima tudumishi Kuchukia Uhalisi kama Msingi <a class="header-anchor" href="#_2-kwa-nini-lazima-tudumishi-kuchukia-uhalisi-kama-msingi" aria-label="Permalink to &quot;2. Kwa nini lazima tudumishi Kuchukia Uhalisi kama Msingi&quot;">​</a></h2><h3 id="_2-1-kuzuia-mkanganyiko-kati-ya-ufisadi-na-uhalisi" tabindex="-1">2.1 Kuzuia mkanganyiko kati ya ufisadi na uhalisi <a class="header-anchor" href="#_2-1-kuzuia-mkanganyiko-kati-ya-ufisadi-na-uhalisi" aria-label="Permalink to &quot;2.1 Kuzuia mkanganyiko kati ya ufisadi na uhalisi&quot;">​</a></h3><p>Katika ustaarabu wa uozi, mipangilio ya ulimwengu wa ufisadi mara nyingi ina uwezo mkubwa wa kuvutia. Waozaji wengi hupata uhamasisho wa uozi kutoka kwa riwaya, hadithi za jadi, na ngano, ambayo kwa yenyewe ni kawaida. Lakini ikiwa mipangilio ya ulimwengu wa ufisadi inalinganishwa moja kwa moja na sheria za kweli, itasababisha shida makubwa: kujifunza kulingana na mipangilio ya ufisadi kunaweza kusababisha upotofu wa uozi, kuunda taasisi kulingana na mipangilio ya ufisadi kunaweza kusababisha kutengana na uhalisi, kuchukia wahusika wa ufisadi kama sanamu za kweli kunaweza kusababisha kupotea kwa roho. Kazi ya kwanza ya msimamo wa kuchukia uhalisi kama msingi ni kutoa mipaka kati ya ufisadi na uhalisi, na kuzuia mkanganyiko kati ya zote mbili.</p><h3 id="_2-2-kuhakikisha-usalama-na-ufanisi-wa-mazoezi-ya-uozi" tabindex="-1">2.2 Kuhakikisha usalama na ufanisi wa mazoezi ya uozi <a class="header-anchor" href="#_2-2-kuhakikisha-usalama-na-ufanisi-wa-mazoezi-ya-uozi" aria-label="Permalink to &quot;2.2 Kuhakikisha usalama na ufanisi wa mazoezi ya uozi&quot;">​</a></h3><p>Uozi ni mazoezi makubwa yanayohusisha asili ya uhai na utendaji wa nishati, na nadharia yoyote mbaya inaweza kusababisha matokeo makubwa. Mifumo ya uozi ya ulimwengu wa ufisadi mara nyingi imeundwa na waandishi kwa mahitaji ya hadithi, na inaweza isilingane na sheria za kweli za utendaji wa nishati na sheria za mageuzi ya uhai. Ikiwa mzazi wa uozi anakiga mipangilio ya ufisadi bila kutofautisha, katika kesi nyepesi uozi utakuwa usio na faida na muda utapotea, katika kesi nzito kutakuwa na mgogoro wa nishati, upotofu wa uozi, na hata hatari ya uhai. Msimamo wa kuchukia uhalisi kama msingi unahitaji kwamba nadharia zote za uozi zipite katika kuthibitishwa na uthibitisho wa uhalisi, na kuhakikisha usalama na ufanisi wa mazoezi ya uozi.</p><h3 id="_2-3-kudumisha-utendaji-wa-taasisi-za-ustaarabu" tabindex="-1">2.3 Kudumisha utendaji wa taasisi za ustaarabu <a class="header-anchor" href="#_2-3-kudumisha-utendaji-wa-taasisi-za-ustaarabu" aria-label="Permalink to &quot;2.3 Kudumisha utendaji wa taasisi za ustaarabu&quot;">​</a></h3><p>Michoro ya taasisi za ustaarabu inapaswa kuzingatia mambo ya kisayansi kama vile hali za kijamii za kweli, hali ya rasilimali, na uhusiano wa kabila. Ikiwa imekutengana na uhalisi, na inategemea tu mawazo mazuri au mipangilio ya ufisadi ili kuunda taasisi, taasisi zitakuwa kama majengo hewani na hazitaweza kutekelezwa katika mazoezi. Msimamo wa kuchukia uhalisi kama msingi unahitaji kwamba michoro yote ya taasisi ianze kutoka uhalisi, ipite katika kuthibitishwa wa mazoezi, na iendelee kurekebishwa na kuboreshwa kulingana na mabadiliko ya uhalisi.</p><h3 id="_2-4-kutoa-mbinu-ya-kuaminika-kwa-ubunifu-na-uumbaji" tabindex="-1">2.4 Kutoa mbinu ya kuaminika kwa ubunifu na uumbaji <a class="header-anchor" href="#_2-4-kutoa-mbinu-ya-kuaminika-kwa-ubunifu-na-uumbaji" aria-label="Permalink to &quot;2.4 Kutoa mbinu ya kuaminika kwa ubunifu na uumbaji&quot;">​</a></h3><p>Kuchukia uhalisi kama msingi hakimaanishi kupunguza ubunifu na mawazo, lakini kutoa mbinu ya kuaminika kwa ubunifu na mawazo. Ufisadi unaweza kutumika kama vyanzo vya uhamasisho na zana za majaribio ya akili, lakini uumbaji wa kweli unapaswa kuzingatia uelewa wa kina wa sheria za kweli. Mambo ambayo hayapo katika uhalisi, kwa kadiri yanalingana na sheria za kisayansi, yanaweza kuundwa; lakini ikiwa yanapingana na sheria za kisayansi, haidhuru mawazo yakivuta, hayataweza kuwa kweli. Msimamo wa kuchukia uhalisi kama msingi unachanganisha &quot;mawazo ya jasusi&quot; na &quot;kuthibitishwa kwa uangalifu&quot;, na kufanya ubunifu uwe msingi imara.</p><h2 id="_3-kanuni-za-kushughulikia-uhusiano-kati-ya-ufisadi-na-uhalisi" tabindex="-1">3. Kanuni za Kushughulikia Uhusiano kati ya Ufisadi na Uhalisi <a class="header-anchor" href="#_3-kanuni-za-kushughulikia-uhusiano-kati-ya-ufisadi-na-uhalisi" aria-label="Permalink to &quot;3. Kanuni za Kushughulikia Uhusiano kati ya Ufisadi na Uhalisi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th><th>Mahitaji Mahususi</th></tr></thead><tbody><tr><td>Kanuni ya Tofautisha</td><td>Tofautisha kwa makini mipangilio ya ufisadi na sheria za kweli</td><td>Nadharia yoyote lazima ionyeshe wazi kama asili yake ni uhamasisho wa ufisadi au kuthibitishwa kweli</td></tr><tr><td>Kanuni ya Kuchimba</td><td>Ufisadi unaweza kutumika kama vyanzo vya uhamasisho na majaribio ya akili</td><td>Shauriwa kupata uhamasisho kutoka ufisadi, lakini lazima upite katika mabadiliko ya sheria za kweli</td></tr><tr><td>Kanuni ya Kuthibitisha</td><td>Nadharia zote lazima zipite katika kuthibitishwa wa mazoezi ya kweli</td><td>Nadharia zisizothibitishwa zinaweza kutumika tu kama dhana, sio msingi wa kuongoza mazoezi</td></tr><tr><td>Kanuni ya Mabadiliko</td><td>Mipangilio ya ufisadi lazima ibadilishwe kuwa fomu inayolingana na sheria za kweli</td><td>Tafsiri upya dhana za ufisadi kwa lugha ya sayansi ya nishati na sayansi ya sheria za kweli</td></tr><tr><td>Kanuni ya Mipaka</td><td>Haki na wajibu wa ulimwengu wa ufisadi havifiki uhalisi</td><td>Usikubali uhalali katika uhalisi wa kitambulisho, mikataba, na sababu na matokeo katika ulimwengu wa ufisadi</td></tr></tbody></table><h2 id="_4-upungufu-wa-ufisadi-unajazwa-na-uhalisi-ambacho-hakipo-katika-uhalisi-kinauzwa-kulingana-na-sasisho-la-sheria" tabindex="-1">4. &quot;Upungufu wa ufisadi unajazwa na uhalisi, ambacho hakipo katika uhalisi kinauzwa kulingana na sasisho la sheria&quot; <a class="header-anchor" href="#_4-upungufu-wa-ufisadi-unajazwa-na-uhalisi-ambacho-hakipo-katika-uhalisi-kinauzwa-kulingana-na-sasisho-la-sheria" aria-label="Permalink to &quot;4. &quot;Upungufu wa ufisadi unajazwa na uhalisi, ambacho hakipo katika uhalisi kinauzwa kulingana na sasisho la sheria&quot;&quot;">​</a></h2><p>Hii ni kanuni kuu ya utendaji ya msimamo wa kuchukia uhalisi kama msingi, na ina njia mbili:</p><h3 id="_4-1-upungufu-wa-ufisadi-unajazwa-na-uhalisi" tabindex="-1">4.1 Upungufu wa ufisadi unajazwa na uhalisi <a class="header-anchor" href="#_4-1-upungufu-wa-ufisadi-unajazwa-na-uhalisi" aria-label="Permalink to &quot;4.1 Upungufu wa ufisadi unajazwa na uhalisi&quot;">​</a></h3><p>Wakati uhamasisho au mipangilio inayopatikana kutoka ulimwengu wa ufisadi haitoshi kamili, haina usawa wenyewe, au hailingani na sheria za kweli, basi inapaswa kujazwa na kusahihishwa kwa kutumia maarifa na sheria zilizothibitishwa tayari katika uhalisi. Kwa mfano, mfumo fulani wa uozi wa ufisadi unaweza tuuelezee mgawanyo wa viwango lakini haielezee utaratibu wa utendaji wa nishati, basi inahitaji kutumia nadharia ya mzunguko wa nishati wa kweli ili kujaza utaratibu wake wa utendaji; teknolojia fulani ya ufisadi inaweza kupingana na sheria ya msingi ya uhifadhi wa nishati, basi inahitaji kutumia sheria za kweli kusahihisha mipangilio yake.</p><p>Mchakato wa kujaza sio tu kuunganisha ufisadi na uhalisi, lakini kuchukia sheria za kweli kama muundo, na kupanga upya vitu vyenye busara katika ufisadi kuwa mfumo wa kibunifu wenye usawa wenyewe na unaolingana na sheria za kweli.</p><h3 id="_4-2-ambacho-hakipo-katika-uhalisi-kinauzwa-kulingana-na-sasisho-la-sheria" tabindex="-1">4.2 Ambacho hakipo katika uhalisi kinauzwa kulingana na sasisho la sheria <a class="header-anchor" href="#_4-2-ambacho-hakipo-katika-uhalisi-kinauzwa-kulingana-na-sasisho-la-sheria" aria-label="Permalink to &quot;4.2 Ambacho hakipo katika uhalisi kinauzwa kulingana na sasisho la sheria&quot;">​</a></h3><p>Wakati kitu fulani au uwezo wa fulani bado hakipo katika uhalisi, lakini uwezo wake wa kuwepo unaweza kutekwa kulingana na sheria za kisayansi zilizothibitishwa tayari, basi inaweza kufanywa sasisho na uumbaji wa busara kulingana na sheria. Uumbaji huu sio mawazo yasiyo na msingi, lakini upanuzi wa kimantiki na utekelezaji wa teknolojia kulingana na sheria zilizopo.</p><p>Kwa mfano, utekelezaji wa teknolojia wa matunda ya kuzidisha ni kesi ya kawaida ya &quot;uumbaji kulingana na sasisho la sheria&quot;. Matunda ya kuzidisha hayupo awali kutoka kwa mipangilio ya kazi za ufisadi, lakini watafiti wa ustaarabu wa usawa wametafsiri upya utaratibu wake wa msingi (kuzidisha kwa kuzidisha) kwa lugha ya sayansi ya nishati na sayansi ya sheria za kweli, na kulingana na sheria za kuzidisha kwa nishati na sauti ya sheria, wameunda teknolojia ya kuzidisha inayoweza kutekelezwa kwa uhandisi. Mchakato huu umetumia uhamasisho wa ufisadi na wakati huo huo umefuata sheria za kweli kwa makini.</p><p>Matokeo ya uumbaji lazima yapite katika kuthibitishwa wa mazoezi. Uumbaji tu ambao umethibitishwa kuwa ufanisi, salama, na thabiti katika uhalisi ndio unaweza kuingizwa katika mfumo rasmi wa ustaarabu wa usawa.</p><h2 id="_5-umatumizi-wa-kuchukia-uhalisi-kama-msingi-katika-nyua-nyingi" tabindex="-1">5. Umatumizi wa Kuchukia Uhalisi kama Msingi katika Nyua Nyingi <a class="header-anchor" href="#_5-umatumizi-wa-kuchukia-uhalisi-kama-msingi-katika-nyua-nyingi" aria-label="Permalink to &quot;5. Umatumizi wa Kuchukia Uhalisi kama Msingi katika Nyua Nyingi&quot;">​</a></h2><h3 id="_5-1-katika-uwanja-wa-uozi" tabindex="-1">5.1 Katika uwanja wa uozi <a class="header-anchor" href="#_5-1-katika-uwanja-wa-uozi" aria-label="Permalink to &quot;5.1 Katika uwanja wa uozi&quot;">​</a></h3><p>Mifumo yote ya uozi lazima ipite katika mchakato wa &quot;kuthibitishwa kweli&quot;: kutoka kwa ujenzi wa kibunifu hadi majaribio ya kiwango cha chini, na kisha utangazaji wa kiwango cha juu, kila hatua lazima iwe na data za athari zinazopimika na zinazoweza kurudiwa. Njia za uozi ambazo hazijapita katika kuthibitishwa kweli zinaweza kutumika tu kama &quot;njia za majaribio&quot;, na ishara za hatari, na hazitawezi kutangazwa kama njia rasmi.</p><h3 id="_5-2-katika-uwanja-wa-teknolojia" tabindex="-1">5.2 Katika uwanja wa teknolojia <a class="header-anchor" href="#_5-2-katika-uwanja-wa-teknolojia" aria-label="Permalink to &quot;5.2 Katika uwanja wa teknolojia&quot;">​</a></h3><p>Teknolojia zote za uhandisi wa sheria lazima zifuata mchakato wa maendeleo wa &quot;kinachowezekana kibunifu — kuthibitishwa kwa majaribio — utekelezaji wa uhandisi — tathmini ya usalama&quot;. Msingi wa kibunifu wa teknolojia lazima uwe sheria ya kisayansi iliyothibitishwa tayari, athari za teknolojia lazima ziwe na viashiria vinavyopimika, na usalama wa teknolojia lazima upite katika tathmini kali.</p><h3 id="_5-3-katika-uwanja-wa-taasisi-za-kijamii" tabindex="-1">5.3 Katika uwanja wa taasisi za kijamii <a class="header-anchor" href="#_5-3-katika-uwanja-wa-taasisi-za-kijamii" aria-label="Permalink to &quot;5.3 Katika uwanja wa taasisi za kijamii&quot;">​</a></h3><p>Michoro yote ya taasisi za kijamii lazima iwe msingi wa uchunguzi wa kijamii wa kweli na uchambuzi wa data. Mabadiliko makubwa ya taasisi lazima yapewe kwanza majaribio ya kiwango cha chini, na baada ya tathmini ya athari basi yatangazwe polepole. Vigezo vya tathmini ya taasisi lazima viwe viashiria vya kweli vinavyopimika, sio dhana za abstract au mipangilio ya ufisadi.</p><h3 id="_5-4-katika-uwanja-wa-historia-na-kale" tabindex="-1">5.4 Katika uwanja wa historia na kale <a class="header-anchor" href="#_5-4-katika-uwanja-wa-historia-na-kale" aria-label="Permalink to &quot;5.4 Katika uwanja wa historia na kale&quot;">​</a></h3><p>Utafiti wa matukio ya kihistoria na ustaarabu wa kale lazima uwe msingi wa ushahidi wa vifaa na vyanzo vya kihistoria vinavyoweza kuthibitishwa. Maudhui ya ngano na hadithi za jadi yanaweza kutumika kama kitu cha utafiti wa kitamaduni, lakini haziwezi kuchukuliwa moja kwa moja kama ukweli wa kihistoria. Kazi ya kale inafuata mpango wa uchafuzi wa chini wa &quot;kioo cha nakala + kale katika mahali tofauti lililogatwa, kurudisha maarifa tu&quot;, na kuhakikisha kuwa kazi ya kale haibadilishi uhalisi wa kihistoria.</p><h2 id="_6-uelewa-wa-kina-wa-dhana-ya-uhalisi" tabindex="-1">6. Uelewa wa Kina wa Dhana ya &quot;Uhalisi&quot; <a class="header-anchor" href="#_6-uelewa-wa-kina-wa-dhana-ya-uhalisi" aria-label="Permalink to &quot;6. Uelewa wa Kina wa Dhana ya &quot;Uhalisi&quot;&quot;">​</a></h2><p>Inahitajika kutaja mahsusi kwamba &quot;uhalisi&quot; katika msimamo wa kuchukia uhalisi kama msingi sio dhana ya tulivu na iliyofungwa, lakini dhana ya mzunguko inayoendelea kueleweka na kupanuliwa.</p><p>Kwanza, upeo wa uhalisi unapanuliwa kila mara pamoja na maendeleo ya ustaarabu. Matukio ambayo zamani yalizingatiwa kuwa &quot;ya kuzidi asili&quot;, pamoja na uelewa wa kina wa nishati na sheria, yameingizwa katika upeo wa uhalisi. Utaratibu wa Nanga, kusafiri kati ya njia, mwingiliano wa kikebe cha fahamu, n.k., kutoka mtazamo wa ustaarabu wa chini inaweza kuonekana kama &quot;ufisadi&quot;, lakini katika uhalisi wa ustaarabu wa juu yapo kwa kisayansi.</p><p>Pili, uelewa wa sheria za kweli unaendelea kina. Nadharia ambayo leo zinaalingatiwa kuwa &quot;sheria&quot;, katika siku zijazo zinaweza kusahihishwa au kuchukuliwa nafasi na nadharia za kina zaidi. Msimamo wa kuchukia uhalisi kama msingi hakimaanishi kudumisha kwa mkasi uelewa uliopo, lakini kushikilia kwa imara mbinu ya msingi ya &quot;mazoezi ni kriteria ya pekee ya kuthibitisha ukweli&quot;, na kuendelea kina uelewa wa uhalisi.</p><p>Tatu, uhalisi una uwezo wa kutokea usio na mwisho. Kulingana na sheria zilizopo, tunaweza kutekwa uwezo mwingi ambao bado haujatekelezwa, na kupitia njia za teknolojia kubadilisha kuwa kweli. Kuchukia uhalisi kama msingi hakimaanishi kupunguza uwezo wa kutokea, lakini kuhakikisha kuwa utekelezaji wa uwezo wa kutokea un msingi wa kuaminika.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kuchukia uhalisi kama msingi ni msimamo wa msingi wa Ustaarabu wa Usawa wa Nanga, na ni hatua ya kwanza na marudio ya nadharia zote na mazoezi ya ustaarabu. Inahitaji kwamba tuwe na mawazo ya wazi, na kuchimba uhamasisho kutoka ufisadi na ngano; na wakati huo huo tuwe na roho ya kweli ya makini, na kuweka uhamasisho wote chini ya kuthibitishwa la sheria za kweli. Upungufu wa ufisadi unajazwa na uhalisi, ambacho hakipo katika uhalisi kinauzwa kulingana na sasisho la sheria — kanuni hii inunganisha kwa kawaida mawazo na uhalisi, uhamasisho na sheria, uumbaji na kuthibitishwa, na kutoa dhamana ya mbinu ya kuaminika kwa mageuzi ya endelevu ya ustaarabu wa usawa.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Muonekano wa Jumla wa Ulimwengu wa Heng Yuan Zhou)</li><li>16-倍增果实技术化原理 (Kanuni ya Utekelezaji wa Teknolojia ya Matunda ya Kuzidisha)</li><li>84-考古协议总纲 (Mpango wa Jumla wa Mkataba wa Kale)</li></ul>',43)])])}const d=i(s,[["render",h]]);export{z as __pageData,d as default};
